const COLORS = [
  ['Red', '#ef4444'], ['Orange', '#f97316'], ['Yellow', '#facc15'], ['Green', '#22c55e'],
  ['Cyan', '#06b6d4'], ['Blue', '#3b82f6'], ['Purple', '#a855f7'], ['White', '#f8fafc']
];
const SIZES = [['Fine', 0.008], ['Medium', 0.018], ['Thick', 0.035]];
const MIN_STEP = 0.012;          // meters between recorded points
const SYNC_MS = 150;             // how often guests get the growing stroke
const MAX_STROKE_POINTS = 1200;  // a longer line continues in a new stroke
const MAX_TOTAL_POINTS = 8000;   // oldest strokes are erased past this
let colorIndex = 0;
let sizeIndex = 1;
let drawing = false;
let strokeId = null;
let points = [];                 // flat [x, y, z, ...] of the current stroke
let lastSync = 0;
const strokes = [];              // { id, count } oldest first

function tipPosition() {
  const tip = ctx.hierarchy.findByName('Brush Tip');
  const pose = tip && ctx.hierarchy.getWorldPose(tip.id);
  return pose ? pose.position : null;
}

function paintTip() {
  const tip = ctx.hierarchy.findByName('Brush Tip');
  if (tip) ctx.world.setComponentField(tip.id, 'meshRenderer', 'color', COLORS[colorIndex][1]);
}

const round = (v) => Math.round(v * 1000) / 1000;

function totalPoints() {
  return strokes.reduce((sum, s) => sum + s.count, 0);
}

function beginStroke(p) {
  strokeId = crypto.randomUUID();
  points = [round(p[0]), round(p[1]), round(p[2])];
  strokes.push({ id: strokeId, count: 1 });
  ctx.world.spawn({
    id: strokeId,
    name: 'Brush Stroke',
    components: [{ type: 'stroke', points: points.slice(), color: COLORS[colorIndex][1], width: SIZES[sizeIndex][1] }]
  });
  lastSync = Date.now();
  while (totalPoints() > MAX_TOTAL_POINTS && strokes.length > 1) ctx.world.deleteSlot(strokes.shift().id);
}

// Updates this peer every time; guests only every SYNC_MS (or when forced).
function pushPoints(force) {
  if (!strokeId) return;
  const now = Date.now();
  const broadcast = force || now - lastSync >= SYNC_MS;
  if (broadcast) lastSync = now;
  ctx.world.setComponentField(strokeId, 'stroke', 'points', points.slice(), broadcast);
  strokes[strokes.length - 1].count = points.length / 3;
}

function endStroke() {
  if (strokeId) pushPoints(true);
  drawing = false;
  strokeId = null;
  points = [];
}

return {
  onSpawn() { paintTip(); },
  onEquip() { paintTip(); },
  onUnequip() { endStroke(); },
  onTrigger(e) {
    if (e.phase === 'press') {
      const p = tipPosition();
      if (!p) return true;
      drawing = true;
      beginStroke(p);
    } else if (e.phase === 'release') {
      endStroke();
    }
    return true;
  },
  tick() {
    if (!drawing || !ctx.world.isHost()) return;
    if (!ctx.equip.isEquipped() && !ctx.grab.isHeld()) { endStroke(); return; }
    const p = tipPosition();
    if (!p || !strokeId) return;
    const n = points.length;
    const from = [points[n - 3], points[n - 2], points[n - 1]];
    if (ctx.math.vecLength(ctx.math.vecSub(p, from)) < MIN_STEP) {
      pushPoints(false); // nothing new, but flush a pending update once SYNC_MS has passed
      return;
    }
    points.push(round(p[0]), round(p[1]), round(p[2]));
    if (points.length / 3 >= MAX_STROKE_POINTS) {
      pushPoints(true);
      beginStroke(p); // continue the line seamlessly in a fresh stroke
      return;
    }
    pushPoints(false);
  },
  getRadialItems() {
    return [
      { label: 'Color: ' + COLORS[colorIndex][0], isEnabled: () => true, onSelect: () => { colorIndex = (colorIndex + 1) % COLORS.length; paintTip(); } },
      { label: 'Size: ' + SIZES[sizeIndex][0], isEnabled: () => true, onSelect: () => { sizeIndex = (sizeIndex + 1) % SIZES.length; } },
      { label: 'Clear strokes', isEnabled: () => strokes.length > 0, onSelect: () => { while (strokes.length) ctx.world.deleteSlot(strokes.pop().id); strokeId = null; points = []; } }
    ];
  }
};

const RANGE = 1.4;          // max reach of the jet
const CLEAN_RADIUS = 0.17;  // per-face UV-space radius cleaned around the hit point (0-1)
const CLEAN_RATE = 0.55;    // fraction of coverage removed per tick within the radius
const SYNC_MS = 120;        // how often guests get the growing clean spot
const BEAM_SYNC_MS = 40;    // how often the beam's endpoints are pushed to guests
const ATLAS_COLS = 3;       // must match surfaceMaskRenderer.ts's box atlas layout
const ATLAS_ROWS = 2;
let spraying = false;
let beamId = null;
let lastMaskSync = 0;
let lastBeamSync = 0;

function nozzlePose() {
  const tip = ctx.hierarchy.findByName('Washer Nozzle');
  return tip ? ctx.hierarchy.getWorldPose(tip.id) : null;
}

function decodeMask(b64, size) {
  const bin = atob(b64);
  const arr = new Uint8ClampedArray(size);
  for (let i = 0; i < arr.length && i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

function encodeMask(arr) {
  let bin = '';
  for (let i = 0; i < arr.length; i++) bin += String.fromCharCode(arr[i]);
  return btoa(bin);
}

// Babylon's box builder order (boxBuilder.js CreateBoxVertexData's "normals"
// array): +Z, -Z, +X, -X, +Y, -Y — surfaceMaskRenderer.ts's atlas cells follow
// this same order, so identifying the hit face this way lands on the matching cell.
function faceIndexFromNormal(normal, rotation) {
  const inv = [-rotation[0], -rotation[1], -rotation[2], rotation[3]];
  const local = ctx.math.rotateVec(inv, normal);
  const ax = Math.abs(local[0]), ay = Math.abs(local[1]), az = Math.abs(local[2]);
  if (az >= ax && az >= ay) return local[2] > 0 ? 0 : 1;
  if (ax >= ay && ax >= az) return local[0] > 0 ? 2 : 3;
  return local[1] > 0 ? 4 : 5;
}

// Erodes a surfaceMask's coverage around a raycast hit — any object with a
// surfaceMask can be cleaned this way, not just the lobby's dirty cube. A box
// host is laid out as a 3x2 face atlas (see surfaceMaskRenderer.ts), so the
// hit's face is identified from its normal and mapped into that face's cell;
// any other shape uses its single, already-unique UV region directly.
function cleanAt(hit) {
  const target = ctx.hierarchy.getSlot(hit.slotId);
  const mask = target && target.components.find((c) => c.type === 'surfaceMask');
  if (!mask) return;
  const meshRef = target.components.find((c) => c.type === 'meshRenderer')?.meshRef;
  const isBox = !!meshRef && meshRef.kind === 'builtin' && meshRef.id === 'box';
  const cols = isBox ? ATLAS_COLS : 1;
  const rows = isBox ? ATLAS_ROWS : 1;
  const cell = mask.resolution;
  const width = cell * cols;
  const height = cell * rows;
  const bytes = decodeMask(mask.mask, width * height);

  let u = hit.u;
  let v = hit.v;
  if (isBox) {
    const faceIndex = faceIndexFromNormal(hit.normal, target.rotation);
    const col = faceIndex % ATLAS_COLS;
    const row = Math.floor(faceIndex / ATLAS_COLS);
    u = (col + hit.u) / ATLAS_COLS;
    v = (row + hit.v) / ATLAS_ROWS;
  }

  const cx = u * width;
  const cy = v * height;
  const radiusPx = CLEAN_RADIUS * cell;
  const minX = Math.max(0, Math.floor(cx - radiusPx));
  const maxX = Math.min(width - 1, Math.ceil(cx + radiusPx));
  const minY = Math.max(0, Math.floor(cy - radiusPx));
  const maxY = Math.min(height - 1, Math.ceil(cy + radiusPx));
  let changed = false;
  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const dx = x + 0.5 - cx;
      const dy = y + 0.5 - cy;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > radiusPx) continue;
      const i = y * width + x;
      const next = bytes[i] - 255 * CLEAN_RATE * (1 - dist / radiusPx);
      if (next < bytes[i]) {
        bytes[i] = next < 0 ? 0 : next;
        changed = true;
      }
    }
  }
  if (!changed) return;
  const now = Date.now();
  const broadcast = now - lastMaskSync >= SYNC_MS;
  if (broadcast) lastMaskSync = now;
  ctx.world.setComponentField(hit.slotId, 'surfaceMask', 'mask', encodeMask(bytes), broadcast);
}

function beamPoints(from, to) {
  return [from[0], from[1], from[2], to[0], to[1], to[2]];
}

function startBeam(from, to) {
  beamId = crypto.randomUUID();
  ctx.world.spawn({ id: beamId, name: 'Water Jet', components: [{ type: 'stroke', points: beamPoints(from, to), color: '#8ee3ff', width: 0.045 }] });
  lastBeamSync = Date.now();
}

function updateBeam(from, to) {
  if (!beamId) return;
  const now = Date.now();
  const broadcast = now - lastBeamSync >= BEAM_SYNC_MS;
  if (broadcast) lastBeamSync = now;
  ctx.world.setComponentField(beamId, 'stroke', 'points', beamPoints(from, to), broadcast);
}

function endBeam() {
  if (beamId) ctx.world.deleteSlot(beamId);
  beamId = null;
}

function spray() {
  const pose = nozzlePose();
  if (!pose) return;
  const origin = ctx.math.vecAdd(pose.position, ctx.math.vecScale(pose.forward, 0.03));
  const hit = ctx.world.raycast(origin, pose.forward, RANGE);
  const target = hit ? hit.point : ctx.math.vecAdd(pose.position, ctx.math.vecScale(pose.forward, RANGE));
  if (!beamId) startBeam(pose.position, target);
  else updateBeam(pose.position, target);
  if (hit) cleanAt(hit);
}

return {
  onTrigger(e) {
    if (e.phase === 'press') spraying = true;
    else if (e.phase === 'release') { spraying = false; endBeam(); }
    return true;
  },
  onUnequip() { spraying = false; endBeam(); },
  tick() {
    if (!spraying || !ctx.world.isHost()) return;
    if (!ctx.equip.isEquipped() && !ctx.grab.isHeld()) { spraying = false; endBeam(); return; }
    spray();
  }
};

const ROOT = ctx.self.id;
const PREFIX = 'lobby-polyhaven-';
const PAGE_SIZE = 5;
let query = '';
let page = 0;
let results = [];
let request = 0;
let importing = false;

function set(id, field, value, broadcast = true) {
  ctx.world.setComponentField(PREFIX + id, 'uiElement', field, value, broadcast);
}
function status(message) { set('status', 'text', message); }
function errorMessage(error) { return error instanceof Error ? error.message : 'Unknown error'; }

async function search(nextPage) {
  if (!ctx.world.isHost()) return;
  const serial = ++request;
  const nextQuery = query.trim();
  status('Searching Poly Haven...');
  try {
    const params = new URLSearchParams({ q: nextQuery, page: String(nextPage) });
    const response = await fetch('/api/polyhaven/models?' + params);
    const data = await response.json();
    if (!response.ok) throw new Error(data.message || 'Search failed.');
    if (serial !== request || !ctx.hierarchy.getSlot(ROOT)) return;
    page = data.page;
    results = data.results;
    for (let i = 0; i < PAGE_SIZE; i++) {
      const model = results[i];
      set('row-' + i, 'visible', !!model, false);
      if (!model) continue;
      set('thumb-' + i, 'src', model.thumbnail || '', false);
      set('name-' + i, 'text', model.name + '\n' + model.category, false);
    }
    set('previous', 'visible', page > 0, false);
    set('next', 'visible', (page + 1) * PAGE_SIZE < data.total, false);
    status(data.total + ' models · Page ' + (page + 1) + ' · CC0');
  } catch (error) {
    if (serial === request) status('Search failed: ' + errorMessage(error));
  }
}

async function importModel(index) {
  if (importing || !results[index]) return;
  const model = results[index];
  importing = true;
  status('Importing ' + model.name + '...');
  try {
    await ctx.assets.importPolyHavenModel(model.id, model.name);
    if (ctx.hierarchy.getSlot(ROOT)) status('Saved ' + model.name + ' to the host Local inventory.');
  } catch (error) {
    if (ctx.hierarchy.getSlot(ROOT)) status('Import failed: ' + errorMessage(error));
  } finally {
    importing = false;
  }
}

return {
  onSpawn() { if (ctx.world.isHost()) void search(0); },
  onUIEvent(event) {
    if (event.slotId === PREFIX + 'query' && (event.type === 'change' || event.type === 'submit')) {
      query = event.text || '';
      if (event.type === 'submit') void search(0);
      return;
    }
    if (event.type !== 'press') return;
    if (event.slotId === PREFIX + 'search') void search(0);
    else if (event.slotId === PREFIX + 'previous' && page > 0) void search(page - 1);
    else if (event.slotId === PREFIX + 'next') void search(page + 1);
    else {
      const match = event.slotId.match(/^lobby-polyhaven-import-(\d)$/);
      if (match) void importModel(Number(match[1]));
    }
  }
};
